<template>
  <main class="app-container pc-page">
    <h1>审计与评测</h1><p class="pc-muted">工具允许、拒绝、批准和回执均可追溯。脚本控制、模型实测、业务验收与用户接受分别记录。</p>
    <div class="pc-toolbar"><el-button @click="reload">刷新记录</el-button></div>
    <el-alert v-if="workspaceError || pageError || error" :title="workspaceError || pageError || error" type="error" :closable="false" />
    <OperationTask :task-id="operationTaskId" :directory-context-id="directoryContextId" title="Harness 复盘" @settled="reload" /><el-tabs v-model="tab">
      <el-tab-pane label="操作与工具证据" name="audit" v-if="checkPermi(['paicli:audit:read'])"><el-form inline @submit.prevent="queryAudit"><el-form-item label="任务 ID"><el-input v-model="filter.taskId" clearable /></el-form-item><el-form-item label="完整工具名"><el-input v-model="filter.toolName" clearable /></el-form-item><el-form-item label="裁决"><el-select v-model="filter.decision" style="width:180px" clearable><el-option label="工具许可" value="PERMITTED" /><el-option label="策略拒绝" value="DENIED" /><el-option label="等待批准" value="PENDING" /><el-option label="人工批准" value="APPROVED" /><el-option label="人工拒绝" value="REJECTED" /><el-option label="修订" value="REVISED" /><el-option label="跳过" value="SKIPPED" /><el-option label="许可已消费" value="ACCEPTED" /><el-option label="执行完成" value="COMPLETED" /><el-option label="执行失败" value="FAILED" /><el-option label="执行取消" value="CANCELLED" /><el-option label="迟到回执已归档" value="LATE_ARCHIVED" /></el-select></el-form-item><el-form-item><el-button type="primary" native-type="submit" :loading="loading" :disabled="!directoryContextId">查询</el-button><el-button v-hasPermi="['paicli:audit:export']" :loading="busy" :disabled="!directoryContextId" @click="exportRows">导出当前范围</el-button></el-form-item></el-form><el-table v-loading="loading" :data="entries"><el-table-column label="时间" min-width="180"><template #default="{ row }">{{ displayTime(row.occurredAt) }}</template></el-table-column><el-table-column prop="userName" label="操作者" width="100" /><el-table-column prop="action" label="动作" width="140" /><el-table-column prop="toolName" label="工具" min-width="160" /><el-table-column prop="decision" label="裁决" width="100" /><el-table-column prop="reason" label="原因" min-width="220" /><el-table-column label="证据" width="170"><template #default="{ row }"><el-tag :type="row.evidenceComplete ? 'success' : 'warning'">{{ row.evidenceComplete ? '引用齐全' : '证据不足，不可判定' }}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template #default="{ row }"><el-button v-hasPermi="['paicli:audit:raw']" link @click="showAudit(row.id)">核对关联记录</el-button></template></el-table-column></el-table><el-empty v-if="!entries.length && !loading" description="当前范围没有审计记录" /><Pagination v-if="total" v-model:page="filter.pageNum" v-model:limit="filter.pageSize" :total="total" @pagination="loadAudit" /></el-tab-pane>
      <el-tab-pane label="Better Harness 复盘" name="harness" v-if="checkPermi(['paicli:evaluation:read'])"><el-alert title="Harness 复盘可引用工具结果和检查报告；模型解释不能替代独立检查。quick / normal / inline 沿用原行为。" type="info" :closable="false" /><el-form inline><el-form-item label="会话"><el-select v-model="harnessSessionId" style="width:300px"><el-option v-for="session in sessions" :key="session.id" :label="session.title" :value="session.id" /></el-select></el-form-item><el-form-item label="复盘方式"><el-select v-model="harnessMode" style="width:160px"><el-option label="quick" value="QUICK" /><el-option label="normal" value="NORMAL" /><el-option label="inline" value="INLINE" /></el-select></el-form-item><el-button v-hasPermi="['paicli:evaluation:run']" type="primary" :loading="busy" :disabled="!harnessSessionId" @click="runReview">申请复盘</el-button></el-form><el-table :data="harness"><el-table-column prop="sessionId" label="会话" /><el-table-column prop="mode" label="方式" width="100" /><el-table-column label="状态"><template #default="{ row }">{{ stateName(row.status) }}</template></el-table-column><el-table-column prop="summary" label="摘要 / inline 输出" min-width="250" /><el-table-column label="时间" min-width="180"><template #default="{ row }">{{ displayTime(row.createdAt) }}</template></el-table-column><el-table-column label="报告"><template #default="{ row }"><el-button v-if="row.reportArtifactId" v-hasPermi="['paicli:artifact:read']" link @click="download(row.reportArtifactId,`harness-${row.id}.json`)">下载完整报告</el-button><span v-else>尚无报告产物</span></template></el-table-column></el-table><el-empty v-if="!harness.length" description="当前没有已登记复盘结果" /></el-tab-pane>
      <el-tab-pane label="Judge / AgentBench 与缺口" name="evaluation" v-if="checkPermi(['paicli:evaluation:read'])"><el-alert title="正式评测保持暂停，页面不提供绕过暂停的运行入口。历史资料或脚本检查不计作正式模型成绩。" type="warning" :closable="false" /><div class="pc-actions"><el-button v-hasPermi="['paicli:evaluation:run']" :disabled="!directoryContextId" @click="openUpload('EVALUATION_REPORT')">导入评测报告资料</el-button><el-button disabled>正式模型评测暂停</el-button></div><section v-for="evaluation in evaluations" :key="evaluation.id" class="pc-panel evaluation"><h2>{{ evaluation.name }} · {{ evaluation.kind }}</h2><p>{{ stateName(evaluation.status) }} · {{ evaluation.paused ? '正式执行暂停' : '仍须单独核对真实执行授权' }}</p><el-alert v-if="!evaluation.publishable || evaluation.formalScores === null" title="正式分数为空或不可发布；不显示正式总榜。" type="warning" :closable="false" /><el-table v-else :data="Object.entries(evaluation.formalScores).map(([name,score]) => ({ name,score }))"><el-table-column prop="name" label="已核实模型 / 配方" /><el-table-column prop="score" label="正式分数" /></el-table><h3 v-if="evaluation.gaps.length">待补能力与配方差距</h3><ul><li v-for="gap in evaluation.gaps" :key="gap">{{ gap }}</li></ul><h3 v-if="evaluation.missingEvidence.length">缺失证据</h3><ul><li v-for="missing in evaluation.missingEvidence" :key="missing">{{ missing }}</li></ul><el-table v-if="evaluation.controlResults?.length" :data="evaluation.controlResults"><el-table-column prop="name" label="脚本控制项" /><el-table-column prop="result" label="控制结果" /><el-table-column prop="evidence" label="证据引用" /></el-table><el-button v-if="evaluation.reportArtifactId" v-hasPermi="['paicli:artifact:read']" @click="download(evaluation.reportArtifactId,`evaluation-${evaluation.id}.json`)">下载归档报告</el-button></section><el-empty v-if="!evaluations.length" description="没有登记评测资料；不代表正式评测已完成" /></el-tab-pane>
      <el-tab-pane label="历史导入与恢复" name="import" v-if="checkPermi(['paicli:import:read'])"><el-alert title="先只读预检来源、身份、范围和秘密，再导入。旧 running 任务进入待核对，旧批准全部过期；撤销不得覆盖后来编辑。" type="warning" :closable="false" /><el-button v-hasPermi="['paicli:import:manage']" :disabled="!directoryContextId" @click="openUpload('LEGACY_IMPORT')">上传脱敏迁移资料并预检</el-button><section v-for="item in imports" :key="item.id" class="pc-panel evaluation"><h2>批次 {{ item.id }} · {{ stateName(item.status) }}</h2><p class="pc-muted">来源指纹 {{ item.fingerprint }} · 版本 {{ item.version }}</p><el-descriptions :column="3" border><el-descriptions-item v-for="(count,name) in item.counts" :key="name" :label="String(name)">{{ count }}</el-descriptions-item></el-descriptions><el-alert v-if="item.containsSecrets" title="发现秘密，禁止导入。请移除凭证正文并重新预检。" type="error" :closable="false" /><ul><li v-for="warning in [...item.warnings,...item.conflicts]" :key="warning">{{ warning }}</li></ul><p v-if="item.unmappedIdentities.length">未映射身份：{{ item.unmappedIdentities.join('、') }}，这些资料不能归属超级管理员。</p><div class="pc-actions"><el-button v-hasPermi="['paicli:import:manage']" type="primary" :loading="busy" :disabled="!item.canImport || item.containsSecrets || item.unmappedIdentities.length > 0 || item.status !== 'PREFLIGHT'" @click="commitImport(item)">按预检版本导入</el-button><el-button v-hasPermi="['paicli:import:manage']" type="danger" :loading="busy" :disabled="item.status !== 'COMMITTED'" @click="revokeImport(item)">预检撤销本批次</el-button><el-button v-if="item.reportArtifactId" v-hasPermi="['paicli:artifact:read']" @click="download(item.reportArtifactId,`import-${item.id}.json`)">查看完整冲突报告</el-button></div></section><el-empty v-if="!imports.length" description="当前没有导入批次" /></el-tab-pane>
    </el-tabs>
    <el-drawer v-model="auditOpen" title="审计关联与证据核对" size="700px"><template v-if="selectedAudit"><el-descriptions :column="1" border><el-descriptions-item label="任务 / 会话">{{ selectedAudit.taskId }} / {{ selectedAudit.sessionId }}</el-descriptions-item><el-descriptions-item label="批准引用">{{ selectedAudit.approvalId || '无人工批准' }}</el-descriptions-item><el-descriptions-item label="事件序号">{{ selectedAudit.eventSequence ?? '未上报' }}</el-descriptions-item><el-descriptions-item label="动作 / 工具">{{ selectedAudit.action }} / {{ selectedAudit.toolName }}</el-descriptions-item><el-descriptions-item label="裁决 / 原因">{{ selectedAudit.decision }} / {{ selectedAudit.reason }}</el-descriptions-item><el-descriptions-item label="用量">{{ selectedAudit.usage ? `${selectedAudit.usage.totalTokens} Token / ${selectedAudit.usage.source}` : '缺供应商回执' }}</el-descriptions-item></el-descriptions><el-alert v-if="!selectedAudit.evidenceComplete" title="证据不足，不能判定执行通过，也不能以 0 分代替未评测。" type="warning" :closable="false" /><pre v-hasPermi="['paicli:audit:raw']" class="pc-pre">{{ safeText(selectedAudit.details) }}</pre><el-button v-if="selectedAudit.artifactId" v-hasPermi="['paicli:artifact:read']" @click="download(selectedAudit.artifactId,`audit-${selectedAudit.id}.json`)">下载获授权原始证据</el-button></template></el-drawer>
    <el-dialog v-model="uploadOpen" :title="uploadPurpose === 'LEGACY_IMPORT' ? '脱敏迁移资料预检' : '归档评测报告'" width="700px" class="pc-dialog"><el-alert :title="uploadPurpose === 'LEGACY_IMPORT' ? '仅上传 export-legacy 导出的 paicli-legacy-v1 脱敏 JSON，最多 16MB；服务端验证 schema、哈希与归属。' : '上传脱敏评测报告资料，最多 50MB；归档不代表正式评测已完成。'" type="warning" :closable="false" /><label class="pc-label" for="pc-data-file">资料文件</label><input id="pc-data-file" type="file" :accept="uploadPurpose === 'LEGACY_IMPORT' ? '.json' : '.json,.jsonl,.zip'" :disabled="busy" @change="selectDataFile" /><p v-if="dataFile">{{ dataFile.name }} · {{ dataFile.size }}B</p><template v-if="uploadPurpose === 'LEGACY_IMPORT'"><label class="pc-label" for="pc-identity-map">旧身份 → 若依用户 ID 映射（JSON 对象）</label><el-input id="pc-identity-map" v-model="identityMappings" type="textarea" :rows="5" placeholder='{"legacy-user":"ruoyi-user-id"}' /><label class="pc-label" for="pc-attachment-map">源附件 SHA-256 → 已上传的中心产物 ID（可选）</label><el-input id="pc-attachment-map" v-model="attachmentMappings" type="textarea" :rows="4" placeholder='{"完整源SHA256":"中心数字ID"}' /><p class="pc-muted">只映射已经明确上传且同目录、目标 owner、摘要一致的产物；中心预检与正式提交均重新核对版本。</p></template><el-alert v-if="error || uploadError" :title="error || uploadError" type="error" :closable="false" /><template #footer><el-button @click="uploadOpen = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!dataFile" @click="upload">{{ uploadPurpose === 'LEGACY_IMPORT' ? '上传并只读预检' : '导入归档资料' }}</el-button></template></el-dialog>
  </main>
</template>
<script setup lang="ts">
import { onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ElMessageBox } from 'element-plus'
import Pagination from '@/components/Pagination/index.vue'
import { checkPermi } from '@/utils/permission'
import OperationTask from '../components/OperationTask.vue'
import { exportAudit, getAudit, getImports, importAction, listAudit, listEvaluations, listHarness, preflightImport, prepareEvaluation, runHarness, uploadDataArtifact } from '@/api/paicli/audit'
import { downloadArtifact, listSessions } from '@/api/paicli/sessions'
import type { PcAuditEntry, PcEvaluation, PcHarness, PcImportPreview, PcSession } from '@/types/paicli'
import { useOperations } from '../useOperations'
import { usePersonalContext } from '../usePersonalContext'
import { displayTime, errorText, operationKeys, safeText, saveDownload, stateName } from '../model'
import { parseAttachmentMappings } from '../shared/registrationInputs'
import '../page.css'
defineOptions({ name:'PaicliAudit' })
const personal=usePersonalContext(), directoryContextId=personal.directoryContextId, workspaceError=personal.error, loadWorkspaces=personal.load, { busy,error,run } = useOperations(), keys = operationKeys()
const operationTaskId=ref('')
const tab = ref(checkPermi(['paicli:audit:read'])?'audit':checkPermi(['paicli:evaluation:read'])?'harness':'import'), pageError = ref(''), loading = ref(false), entries = ref<PcAuditEntry[]>([]), total = ref(0), selectedAudit = ref<PcAuditEntry>(), auditOpen = ref(false), harness = ref<PcHarness[]>([]), evaluations = ref<PcEvaluation[]>([]), imports = ref<PcImportPreview[]>([]), sessions = ref<PcSession[]>([]), harnessSessionId = ref(''), harnessMode = ref<PcHarness['mode']>('QUICK'), uploadOpen = ref(false), uploadPurpose = ref<'LEGACY_IMPORT'|'EVALUATION_REPORT'>('LEGACY_IMPORT'), dataFile = ref<File>(), identityMappings = ref('{}'), attachmentMappings=ref('{}'), uploadError = ref('')
const filter = reactive({ pageNum:1,pageSize:20,taskId:'',toolName:'',decision:'' })
let generation = 0, listGeneration = 0, auditGeneration = 0
async function loadAudit() { const g = ++listGeneration,id = directoryContextId.value; if (!id) return; loading.value = true; try { const response = await listAudit({ ...filter,directoryContextId:id }); if (g === listGeneration && id === directoryContextId.value) { entries.value = response.rows; total.value = response.total } } catch(cause) { if (g === listGeneration) pageError.value = errorText(cause) } finally { if (g === listGeneration) loading.value = false } }
function queryAudit() { filter.pageNum = 1; void loadAudit() }
async function reload() { const id = directoryContextId.value,g = ++generation; if (!id) return; pageError.value = ''; const results = await Promise.allSettled([checkPermi(['paicli:audit:read']) ? loadAudit() : Promise.resolve(),checkPermi(['paicli:evaluation:read']) ? listHarness(id) : Promise.resolve({data:[]}),checkPermi(['paicli:evaluation:read']) ? listEvaluations(id) : Promise.resolve({data:[]}),checkPermi(['paicli:import:read']) ? getImports(id) : Promise.resolve({data:[]}),checkPermi(['paicli:session:read']) ? listSessions(id,1,100) : Promise.resolve({rows:[]})]); if (g !== generation || id !== directoryContextId.value) return; const errors: string[] = []; results.forEach((result,i) => { if (result.status === 'rejected') { errors.push(errorText(result.reason)); return }; if (i === 1) harness.value = (result.value as Awaited<ReturnType<typeof listHarness>>).data; if (i === 2) evaluations.value = (result.value as Awaited<ReturnType<typeof listEvaluations>>).data; if (i === 3) imports.value = (result.value as Awaited<ReturnType<typeof getImports>>).data; if (i === 4) sessions.value = (result.value as Awaited<ReturnType<typeof listSessions>>).rows }); if (errors.length) pageError.value = [pageError.value,...errors].filter(Boolean).join('；') }
async function showAudit(id: string) { const g = ++auditGeneration; await run(async () => { const response = await getAudit(id); if (g === auditGeneration) { selectedAudit.value = response.data; auditOpen.value = true } }) }
async function exportRows() { const params = { ...filter,directoryContextId:directoryContextId.value }; await run(async () => saveDownload(await exportAudit(params),`paicli-audit-${directoryContextId.value}.json`)) }
async function download(id: string,name: string) { await run(async () => saveDownload(await downloadArtifact(id),name)) }
async function runReview() { const intent = { action:'harness',sessionId:harnessSessionId.value,mode:harnessMode.value }; await run(async () => { const result=(await runHarness(intent.sessionId,intent.mode,keys.get(intent))).data;operationTaskId.value=result.taskId || ''; keys.done(intent); await reload() }) }
function openUpload(purpose: 'LEGACY_IMPORT'|'EVALUATION_REPORT') { uploadPurpose.value = purpose; dataFile.value = undefined; uploadError.value = ''; identityMappings.value = '{}'; attachmentMappings.value='{}';error.value = ''; uploadOpen.value = true }
function selectDataFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0], legacy = uploadPurpose.value === 'LEGACY_IMPORT', limit = legacy ? 16 : 50; if (file && (file.size > limit * 1024 * 1024 || (legacy && !file.name.toLowerCase().endsWith('.json')))) { uploadError.value = legacy ? '历史迁移仅接受 paicli-legacy-v1 JSON，最多 16MB / 10000 条记录；请用 export-legacy 按来源拆分导出。' : '归档报告超过 50MB，请先拆分。'; dataFile.value = undefined; return }; dataFile.value = file; uploadError.value = '' }
async function upload() { const file = dataFile.value; if (!file) return; let mappings: Record<string,string> = {},attachments:Record<string,string>={}; try { const parsed: unknown = JSON.parse(identityMappings.value); if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || Object.values(parsed).some(value => typeof value !== 'string')) throw new Error('身份映射须为字符串 ID 对象'); mappings = parsed as Record<string,string>;if(uploadPurpose.value === 'LEGACY_IMPORT')attachments=parseAttachmentMappings(attachmentMappings.value) } catch(cause) { uploadError.value = errorText(cause); return }; const id = directoryContextId.value,purpose = uploadPurpose.value,intent = { id,purpose,name:file.name,size:file.size,modified:file.lastModified,mappings,attachments }; await run(async () => { const artifact = (await uploadDataArtifact(id,file,purpose,keys.get({ ...intent,action:'upload' }))).data; if (purpose === 'LEGACY_IMPORT') await preflightImport(id,artifact.id,mappings,keys.get({ ...intent,artifactId:artifact.id,action:'preflight' }),attachments); else await prepareEvaluation(id,artifact.id,keys.get({ ...intent,artifactId:artifact.id,action:'report' })); uploadOpen.value = false; await reload() }) }
async function commitImport(item: PcImportPreview) { if (!item.canImport || item.containsSecrets || item.unmappedIdentities.length) return; try { await ElMessageBox.confirm('将按预检哈希与身份映射导入本批资料；旧执行任务不会自动重跑，旧批准全部过期。确认执行？','确认本批导入',{ type:'warning' }) } catch { return }; const intent = { id:item.id,version:item.version,action:'COMMIT' }; await run(async () => { await importAction(item.id,'COMMIT',item.version,keys.get(intent)); keys.done(intent); await reload() }) }
async function revokeImport(item: PcImportPreview) { try { await ElMessageBox.confirm('仅撤销本批次未被后来编辑的记录，发生冲突时保留修改并输出清单。确认先核对撤销？','撤销本批导入',{ type:'warning' }) } catch { return }; const intent = { id:item.id,version:item.version,action:'REVOKE' }; await run(async () => { await importAction(item.id,'REVOKE',item.version,keys.get(intent)); keys.done(intent); await reload() }) }
watch(directoryContextId, () => { generation++; listGeneration++; auditGeneration++; operationTaskId.value='';entries.value = []; selectedAudit.value = undefined; auditOpen.value = false; harness.value = []; evaluations.value = []; imports.value = []; sessions.value = []; filter.pageNum = 1; harnessSessionId.value = ''; if (directoryContextId.value) void reload() }); onMounted(loadWorkspaces); onBeforeUnmount(() => { generation++; listGeneration++; auditGeneration++ })
</script>
<style scoped>.evaluation{margin-top:16px}</style>
